import type { ReactNode } from '~/lib/types.ts'
import { Button } from './button.tsx'
import {
  Popover,
  PopoverClose,
  PopoverContent,
  PopoverTrigger,
} from './popover.tsx'
import styles from './popconfirm.module.scss'

export interface PopconfirmProps {
  title: string
  description?: ReactNode
  confirmLabel?: string
  cancelLabel?: string
  destructive?: boolean
  onConfirm: () => void
  children: ReactNode
}

/** Small confirmation popover for destructive or irreversible actions. */
export function Popconfirm({
  title,
  description,
  confirmLabel = 'Confirm',
  cancelLabel = 'Cancel',
  destructive = false,
  onConfirm,
  children,
}: PopconfirmProps) {
  return (
    <Popover>
      {() => (
        <>
          <PopoverTrigger>{children}</PopoverTrigger>
          <PopoverContent side="top" ariaLabel={title}>
            <div className={styles.content}>
              <p className={styles.title}>{title}</p>
              {description ? (
                <p className={styles.description}>{description}</p>
              ) : null}
              <div className={styles.actions}>
                <PopoverClose>
                  <Button size="sm" variant="ghost">
                    {cancelLabel}
                  </Button>
                </PopoverClose>
                <PopoverClose>
                  <Button
                    size="sm"
                    variant={destructive ? 'destructive' : 'primary'}
                    onClick={onConfirm}
                  >
                    {confirmLabel}
                  </Button>
                </PopoverClose>
              </div>
            </div>
          </PopoverContent>
        </>
      )}
    </Popover>
  )
}

@use 'styles' as vz;

.content {
  display: flex;
  width: 100%;
  flex-direction: column;
  gap: vz.space(2);
  padding: vz.space(4);
}

.title {
  margin: 0;
  font-size: vz.font-size('sm');
  font-weight: 600;
}

.description {
  margin: 0;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: vz.space(2);
  padding-top: vz.space(1);
}
